create type public.report_status as enum('open','reviewing','actioned','dismissed','reopened');create type public.moderation_action_status as enum('active','expired','reversed');create type public.duplicate_review_status as enum('open','reviewing','merged','not_duplicate','dismissed');
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_player_id uuid not null references public.players,subject_type text not null check(subject_type in('player','club','match','content')),subject_id uuid not null,reason_code text not null,description text not null,status public.report_status not null default'open',assigned_admin_id uuid references auth.users,resolution_reason text,resolved_at timestamptz,version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index reports_status_created_idx on public.reports(status,created_at);create index reports_subject_idx on public.reports(subject_type,subject_id,created_at desc);
create table public.report_evidence(report_id uuid not null references public.reports on delete cascade,evidence_object_id uuid not null references private.evidence_objects,added_by uuid not null references public.players,created_at timestamptz not null default now(),primary key(report_id,evidence_object_id));
create table public.moderation_actions(id uuid primary key default gen_random_uuid(),report_id uuid references public.reports,subject_type text not null,subject_id uuid not null,action_type text not null,reason text not null,status public.moderation_action_status not null default'active',effective_at timestamptz not null default now(),expires_at timestamptz,reversed_action_id uuid references public.moderation_actions,actor_admin_id uuid not null references auth.users,request_id uuid not null unique);create index moderation_active_subject_idx on public.moderation_actions(subject_type,subject_id,status,expires_at);
create table public.duplicate_identity_reviews(id uuid primary key default gen_random_uuid(),candidate_player_a_id uuid not null references public.players,candidate_player_b_id uuid not null references public.players,status public.duplicate_review_status not null default'open',evidence_summary text not null,assigned_admin_id uuid references auth.users,decision_reason text,surviving_player_id uuid references public.players,decided_at timestamptz,created_at timestamptz not null default now(),check(candidate_player_a_id<candidate_player_b_id));create unique index duplicate_review_open_pair_idx on public.duplicate_identity_reviews(candidate_player_a_id,candidate_player_b_id)where status in('open','reviewing');
create table private.player_identity_aliases(alias_player_id uuid primary key references public.players,surviving_player_id uuid not null references public.players,review_id uuid not null references public.duplicate_identity_reviews,created_at timestamptz not null default now());
alter table public.reports enable row level security;alter table public.report_evidence enable row level security;alter table public.moderation_actions enable row level security;alter table public.duplicate_identity_reviews enable row level security;create policy report_owner_or_admin_read on public.reports for select to authenticated using(reporter_player_id=public.current_player_id()or public.is_platform_admin());create policy report_evidence_owner_or_admin_read on public.report_evidence for select to authenticated using(exists(select 1 from public.reports r where r.id=report_id and(r.reporter_player_id=public.current_player_id()or public.is_platform_admin())));create policy moderation_admin_read on public.moderation_actions for select to authenticated using(public.is_platform_admin());create policy duplicate_admin_read on public.duplicate_identity_reviews for select to authenticated using(public.is_platform_admin());grant select on public.reports,public.report_evidence,public.moderation_actions,public.duplicate_identity_reviews to authenticated;revoke insert,update,delete on public.reports,public.report_evidence,public.moderation_actions,public.duplicate_identity_reviews from anon,authenticated;
